const crypto = require('crypto');
const secret = process.env.N8N_WEBHOOK_SECRET || '4f8b9e2c1a3d5e7f9a0b1c2d3e4f5a6b7c8d9e0f1a2b3c4d5e6f7a8b9c0d1e2f';

const payload = {
  reportId: $node['Webhook Trigger'].json.body.reportId,
  healthScore: 85,
  anomalies: [
    {
      severity: 'Low',
      variance: 3.5,
      description: 'Minor seasonal variance detected in tech infrastructure expenses.'
    }
  ],
  chartData: [
    { month: 'Jan', revenue: 120000, expenses: 85000 },
    { month: 'Feb', revenue: 135000, expenses: 88000 },
    { month: 'Mar', revenue: 142000, expenses: 91000 }
  ],
  expenseBreakdown: [
    { category: 'Payroll', amount: 150000, percentage: 57 },
    { category: 'Technology', amount: 50000, percentage: 19 },
    { category: 'Operations', amount: 40000, percentage: 15 },
    { category: 'Marketing', amount: 24000, percentage: 9 }
  ],
  aiCommentary: 'AI analysis completed: Solid revenue trajectory with controlled operational overhead.'
};

const jsonString = JSON.stringify(payload);
const signature = crypto.createHmac('sha256', secret).update(jsonString).digest('hex');

return {
  json: {
    payload,
    signature
  }
};
